
(()=>{'use strict';
let reportContextCache=[];
const safeText=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
if(window.__RIM_REPORTS_OWNED){/* modular owns reports */}else window.openReportForm=async function(prefill={}){
 const ctx={messageId:prefill.messageId||null,conversationId:prefill.conversationId||null,channelId:prefill.channelId||null,commentId:prefill.commentId||null,contextType:prefill.contextType||null,username:String(prefill.username||'').replace(/^@/,'')};
 let targetId=null;
 if(ctx.messageId){const m=(messagesCache||[]).find(x=>x.id===ctx.messageId);if(m){targetId=m.sender_id;ctx.conversationId=ctx.conversationId||m.conversation_id||activeConversation?.id||null;ctx.contextType=ctx.contextType||(activeConversation?.type==='group'?'group':'message');}}
 if(ctx.commentId){const {data}=await db.from('channel_post_comments').select('id,author_id,post_id,channel_id').eq('id',ctx.commentId).maybeSingle();if(data){targetId=data.author_id;ctx.channelId=ctx.channelId||data.channel_id;ctx.postId=data.post_id;ctx.contextType='channel_comment';}}
 if(targetId&&!ctx.username){const {data}=await db.from('profiles').select('username').eq('id',targetId).maybeSingle();ctx.username=data?.username||'';}
 if(!ctx.contextType)ctx.contextType=ctx.channelId?'channel_post':ctx.username?'user':'message';
 window.__rimPendingReportContext=ctx;
 showModal(`<h2 class="modal-title">⚑ Жалоба</h2><div class="feature-small">${ctx.contextType==='group'?'Сообщение в группе':ctx.contextType==='channel_comment'?'Комментарий в канале':ctx.contextType==='channel_post'?'Публикация канала':'Пользователь или сообщение'}</div><label class="field-label">На кого жалоба (username)</label><input class="field" id="reportUsername" value="${safeText(ctx.username)}" placeholder="username"><label class="field-label">Причина</label><select class="field" id="reportReason"><option value="spam">Спам</option><option value="harassment">Оскорбления или травля</option><option value="scam">Мошенничество</option><option value="inappropriate">Недопустимый контент</option><option value="other">Другое</option></select><label class="field-label">Подробности</label><textarea class="field" id="reportDetails" rows="4" placeholder="Опиши, что именно нарушает правила"></textarea><div class="modal-actions"><button class="action-btn" onclick="closeModal()">Отмена</button><button class="primary-btn" onclick="rimSubmitContextReport()">Отправить</button></div>`);
};
window.rimSubmitContextReport=async function(){
 const ctx=window.__rimPendingReportContext||{};const username=document.getElementById('reportUsername')?.value.trim().replace(/^@/,'')||'';const reason=document.getElementById('reportReason')?.value||'other';const details=document.getElementById('reportDetails')?.value.trim()||'';
 if(!details)return toast('Добавь подробности жалобы.');let targetId=null;
 if(username){const {data,error}=await db.from('profiles').select('id').eq('username',username).maybeSingle();if(error)return featureError('Не удалось найти пользователя',error);if(!data)return toast('Пользователь не найден.');targetId=data.id;}
 else if(ctx.messageId){const m=(messagesCache||[]).find(x=>x.id===ctx.messageId);targetId=m?.sender_id||null;}
 else if(ctx.commentId){const {data}=await db.from('channel_post_comments').select('author_id').eq('id',ctx.commentId).maybeSingle();targetId=data?.author_id||null;}
 const payload={reporter_id:currentUser.id,reported_user_id:targetId,message_id:ctx.messageId||null,conversation_id:ctx.conversationId||null,channel_id:ctx.channelId||null,comment_id:ctx.commentId||null,context_type:ctx.contextType||'user',reason,details};
 const {error}=await db.from('user_reports').insert(payload);if(error)return featureError('Не удалось отправить жалобу',error);closeModal();toast('Жалоба отправлена. Модератор увидит место, на которое она подана.');window.__rimPendingReportContext=null;
};
window.openModeration=async function(){
 if(!isImperator())return toast('Недостаточно прав.');
 const [{data:reports,error:rErr},{data:posts,error:pErr}]=await Promise.all([db.from('user_reports').select('*').order('created_at',{ascending:false}).limit(100),db.from('bulletin_posts').select('*').eq('status','pending').order('created_at',{ascending:false}).limit(50)]);
 if(rErr)return featureError('Не удалось загрузить жалобы',rErr);if(pErr)return featureError('Не удалось загрузить объявления',pErr);reportContextCache=reports||[];
 const userIds=[...new Set(reportContextCache.map(r=>r.reported_user_id).filter(Boolean))];const prof=typeof getProfiles==='function'?await getProfiles(userIds):{};
 const channelIds=[...new Set(reportContextCache.map(r=>r.channel_id).filter(Boolean))];const convIds=[...new Set(reportContextCache.map(r=>r.conversation_id).filter(Boolean))];
 const [{data:channels},{data:convs}]=await Promise.all([channelIds.length?db.from('channels').select('id,title,username').in('id',channelIds):Promise.resolve({data:[]}),convIds.length?db.from('conversations').select('id,title,type').in('id',convIds):Promise.resolve({data:[]})]);
 const chMap=Object.fromEntries((channels||[]).map(x=>[x.id,x]));const cvMap=Object.fromEntries((convs||[]).map(x=>[x.id,x]));
 const rh=reportContextCache.map(r=>{const ch=chMap[r.channel_id],cv=cvMap[r.conversation_id],person=prof?.[r.reported_user_id];const place=ch?`Канал: ${safeText(ch.title)} ${ch.username?'@'+safeText(ch.username):''}`:cv?`Группа: ${safeText(cv.title||'Без названия')}`:r.context_type==='user'?'Профиль пользователя':'Место сообщения';const status={new:'Новая',reviewing:'На рассмотрении',resolved:'Решена',rejected:'Отклонена'}[r.status]||r.status;return `<article class="feature-comment rim-report-card"><div class="row" style="justify-content:space-between;gap:8px"><b>${safeText(r.reason)}</b><span class="badge">${status}</span></div><div>${safeText(r.details||'')}</div><div class="feature-small">${safeText(person?.username?'@'+person.username:'Пользователь')} · ${safeText(place)} · ${formatDate(r.created_at)}</div><div class="feature-actions">${(r.conversation_id||r.channel_id)?`<button class="primary-btn" onclick="rimOpenReportContext('${r.id}')">Открыть место жалобы</button>`:''}<button class="action-btn" onclick="rimSetReportStatus('${r.id}','reviewing')">На рассмотрении</button><button class="action-btn" onclick="rimSetReportStatus('${r.id}','resolved')">Решена</button><button class="action-btn danger-btn" onclick="rimSetReportStatus('${r.id}','rejected')">Отклонить</button></div></article>`;}).join('');
 const ph=(posts||[]).map(p=>`<div class="feature-comment"><b>${safeText(p.title)}</b><div>${safeText(p.body)}</div><div class="feature-actions"><button class="primary-btn" onclick="moderateBulletin('${p.id}','approved')">Одобрить</button><button class="action-btn danger-btn" onclick="moderateBulletin('${p.id}','rejected')">Отклонить</button></div></div>`).join('');
 showModal(`<h2 class="modal-title">⚖ Панель Императора</h2><h3>Жалобы (${reportContextCache.length})</h3>${rh||'<p class="muted">Нет жалоб.</p>'}<h3>Объявления на проверке</h3>${ph||'<p class="muted">Нет объявлений.</p>'}<button class="primary-btn" style="width:100%;margin-top:10px" onclick="closeModal()">Закрыть</button>`);
};
window.rimSetReportStatus=async function(id,status){if(!isImperator())return;const {error}=await db.from('user_reports').update({status,moderator_id:currentUser.id,updated_at:new Date().toISOString()}).eq('id',id);if(error)return featureError('Не удалось обновить жалобу',error);window.openModeration();};
window.rimOpenReportContext=async function(id){const r=reportContextCache.find(x=>x.id===id);if(!r)return toast('Жалоба уже не найдена в списке.');closeModal();
 if(r.channel_id){await openChannel(r.channel_id);if(r.comment_id){const {data:c}=await db.from('channel_post_comments').select('post_id').eq('id',r.comment_id).maybeSingle();if(c?.post_id){const box=document.getElementById('rimComments-'+c.post_id);if(box&&!box.classList.contains('open'))await rimToggleComments(c.post_id);setTimeout(()=>{const el=document.getElementById('rimCommentRows-'+c.post_id);const target=el?.querySelector(`[data-comment-id="${r.comment_id}"]`)||el;if(target){target.scrollIntoView({behavior:'smooth',block:'center'});target.classList.add('rim-report-highlight');}},250);}}return;}
 if(r.conversation_id){await openConversation(r.conversation_id);if(r.message_id){setTimeout(()=>{const el=document.querySelector(`.message[data-id="${r.message_id}"]`);if(el){el.scrollIntoView({behavior:'smooth',block:'center'});el.classList.add('rim-report-highlight');}},350);}return;}
 toast('Для этой жалобы место в переписке не указано.');
};
})();
